import{_ as e,o as t,c as n,a0 as o}from"./chunks/framework.CShDTZbC.js";const h=JSON.parse('{"title":"Saving Your Campaign","description":"","frontmatter":{},"headers":[],"relativePath":"guide/saving.md","filePath":"guide/saving.md"}'),i={name:"guide/saving.md"};function s(r,a,g,p,l,u){return t(),n("div",null,[...a[0]||(a[0]=[o('<h1 id="saving-your-campaign" tabindex="-1">Saving Your Campaign <a class="header-anchor" href="#saving-your-campaign" aria-label="Permalink to &quot;Saving Your Campaign&quot;">​</a></h1><p>Your campaign saves itself quietly at the end of every day.</p><p>Backing out of a game asks what you want:</p><ul><li><strong>Keep playing</strong> — nothing happens.</li><li><strong>Save &amp; quit</strong> — stores the campaign and returns to the menu.</li><li><strong>Quit without saving</strong> — the day&#39;s autosave still stands.</li></ul><p>From the main menu, <strong>Continue</strong> (or <strong>Load Game</strong>) picks the campaign back up exactly where it stood — heroes, gear, research, marches, fog and all.</p><p>The same menu holds the sound, display and battle options — see <a href="/guide/settings.html">Settings &amp; Unlocks</a>.</p><p>You can keep <strong>as many campaigns as you like</strong>. <strong>Load Game</strong> on the main menu lists them all — each with its guild, the day it reached and when you last saved it — and you can delete any you are done with. <strong>Continue</strong> always picks up the one you played most recently.</p><p>Saving again writes back to the campaign in hand rather than making a new copy, so a campaign keeps one entry in the list however long you play it. A game saved by an older version of Athanor is carried into the list automatically the first time you open it.</p><p>Your campaigns are kept on your device.</p>',9)])])}const m=e(i,[["render",s]]);export{h as __pageData,m as default};
